import React from 'react'
import { FormattedMessage } from 'react-intl'
import Content from '../../content'
import { SectionWrapper, OrderedList } from './index.style'

const PrivacyPolicySection = (props) => {
  const { title = '' } = props

  const mailTo = (email) => {
    window.open(`mailto:${email}`)
  }

  return (
    <SectionWrapper>
      <div className='section__header'>{title}</div>
      {Object.keys(Content[title]).map((para) => {
        if (para.includes('subHeading')) {
          return (
            <div className='section__subHeading'>{Content[title][para]}</div>
          )
        }
        if (para.includes('ol')) {
          return (
            <OrderedList>
              {Object.keys(Content[title][para]).map((list) => {
                return (
                  <li>
                    <FormattedMessage
                      id={Content[title][para][list]}
                      defaultMessage={Content[title][para][list]}
                      values={{
                        br: <br />,
                        span: (chunks) => <span>{chunks}</span>
                      }}
                    />
                  </li>
                )
              })}
            </OrderedList>
          )
        }
        return (
          <div className='section__para'>
            <FormattedMessage
              id={Content[title][para]}
              defaultMessage={Content[title][para]}
              values={{
                span: (chunks) => <span className='section__email' onClick={() => mailTo('cs@pasarpolis.com')}>{chunks}</span>
              }}
            />
          </div>
        )
      })}
    </SectionWrapper>
  )
}

export default PrivacyPolicySection
